#!/usr/bin/env bash
# context-budget — AGENTS.md and skill body line ceilings
set -euo pipefail
node -e 'const fs=require("fs"),path=require("path"),c=JSON.parse(process.env.HARNESS_CONFIG_JSON||"{}"),limA=c.limits?.agentsMdLines??200,limS=c.limits?.skillBodyLines??60,base=c.baseline?.agentsMdLines,agents=fs.existsSync("AGENTS.md")?fs.readFileSync("AGENTS.md","utf8").split("\n").length:0,ceil=base!=null?Math.max(limA,base):limA,fail=[];if(base!=null&&base>limA){if(agents>base)fail.push("AGENTS.md "+agents+" > baseline "+base)}else if(agents>ceil)fail.push("AGENTS.md "+agents+" lines; limit "+limA);const sk="harness/skills";if(fs.existsSync(sk))for(const d of fs.readdirSync(sk)){const p=path.join(sk,d,"SKILL.md");if(!fs.existsSync(p))continue;const n=fs.readFileSync(p,"utf8").replace(/^---[\s\S]*?---\n?/,"").split("\n").length;if(n>limS)fail.push(p+" body "+n+" > "+limS)}if(fail.length){console.error(fail.join("\n"));process.exit(1)}console.log("AGENTS.md "+agents+" lines (ceiling "+ceil+"); skills within "+limS)'
